(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--x-sj-prepa-gyneco-j2-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"x-sj-prepa-gyneco-j2-sf3\",\n \"titre\": \"Préparation D.E (J) · J2 Gynéco-obstétrique SF3\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 56,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n   \"sha256\": \"3550add9cf11e4b110725f4453a7ee215d2a92e3248ed3e81db1dc69fc1c1590\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J2 (SF3)\",\n     \"slug\": \"prepa-gyneco-j2-sf3\",\n     \"pages\": \"\",\n     \"count\": 56,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"L'audit du décès fœtal conclut à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un premier retard\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un 2e retard\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un 3e retard\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Un premier retard\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le 1er retard est le retard dans la décision d'aller consulter (méconnaissance des signes de danger, lenteur de la décision). Ici, RPM depuis une semaine et fièvre depuis deux jours avant de venir : le retard est survenu à domicile. Le 2e retard concerne le transport/la référence, le 3e la qualité des soins dans la structure.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Les trois retards (p. 75-76) ; SONU L1 2021\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Parmi les propositions suivantes, laquelle serait pertinente pour évacuer la cavité utérine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Abstention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aspiration par AMIU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Césarienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déclenchement du travail d'accouchement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Déclenchement du travail d'accouchement\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Devant une mort fœtale à 27 SA, l'évacuation se fait par déclenchement artificiel du travail (voie basse), après bilan de coagulation. L'abstention n'est pas indiquée ici (chorioamniotite sévère). L'AMIU est réservée aux grossesses précoces ; la césarienne n'est pas indiquée pour un fœtus mort.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Mort in utero – CAT (déclenchement du travail)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Dans le cas décrit ci-dessus, deux éléments sont des facteurs de risque d'hémorragie du post-partum. Lesquels :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Infection amniotique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'âge\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La mort in utero\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le Rhésus négatif\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Infection amniotique ; D. La mort in utero\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Les facteurs de risque d'hémorragie du post-partum retenus ici sont l'infection amniotique (chorioamniotite → atonie utérine) et la mort in utero (risque de troubles de la coagulation par afibrinogénémie). La fièvre est un signe, l'âge (18 ans) et le Rhésus négatif ne sont pas des facteurs d'HPP.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), HPP (causes des 4T) et Mort in utero – complications\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Dans la prise en charge de cette patiente, différentes molécules peuvent être utilisées : Lesquelles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Syntocinon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lasilix (diurétique)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Misoprostol\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Amoxicilline acide clavulanique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Antispamodique\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Celestène\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Syntocinon ; B. Lasilix (diurétique) ; C. Misoprostol ; D. Amoxicilline acide clavulanique\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Syntocinon et misoprostol servent au déclenchement et à la prévention de l'HPP ; l'amoxicilline-acide clavulanique traite la chorioamniotite. Le Célestène (maturation pulmonaire) n'a pas d'intérêt quand le fœtus est mort ; un antispasmodique n'est pas indiqué.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan) ; MAP – Menace d'accouchement prématuré (PDF) (Célestène = maturation pulmonaire)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Après l'expulsion fœtale, la patiente a choisi de bénéficier d'une méthode contraceptive du post-partum immédiat. Parmi les propositions suivantes, lesquelles sont justifiées :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"DIU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Progestatif injectable\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Implant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. MAMA ; B. DIU\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le cours SSR cite la MAMA et le DIU au cuivre parmi les méthodes du post-partum ; le DIU peut être posé dans les 48 heures après l'accouchement (post-partum immédiat).\\n\\nSource : Document SSR L2 SF 2021, Contraception du post-partum et DIUPP\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Parmi les affections suivantes pouvant survenir au cours de la grossesse, la ou lesquelles sont d'origine parasitaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rubéole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Syphilis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toxoplasmose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Paludisme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Hépatite B\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Toxoplasmose ; D. Paludisme\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La toxoplasmose (Toxoplasma gondii) et le paludisme (Plasmodium) sont des infections parasitaires. La rubéole et l'hépatite B sont virales, la syphilis est bactérienne.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Mort in utero – causes : « infections parasitaires : toxoplasmose ; paludisme »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Les affections suivantes peuvent être immunisantes : Lesquelles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rubéole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Syphilis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toxoplasmose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Rubéole ; C. Toxoplasmose\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Une primo-infection par la rubéole ou la toxoplasmose laisse une immunité durable (IgG). La syphilis et le paludisme n'immunisent pas : réinfection possible.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Toxoplasmose et grossesse (le kyste persiste chez l'hôte immunisé) ; Rubéole et grossesse\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Devant le résultat de la sérologie toxoplasmique suivant, demandé lors du BPN : IgM négatif, IgG positif. Quelle interprétation donnez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Absence d'infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Infection récente débutante\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Infection ancienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection évolutive\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Infection ancienne\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"IgM négatives + IgG positives = la personne a déjà fait la maladie et est guérie (immunisée) : infection ancienne. Les IgM signent une infection récente ou évolutive.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Toxoplasmose – interprétation des sérologies\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Parmi les différents types de virus de l'hépatite, lequel est le plus transmis au cours de la grossesse en Côte d'Ivoire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite A\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hépatite B\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hépatite C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hépatite E\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Hépatite B\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les hépatites virales de la grossesse sont dominées par l'hépatite B ; sa PTME est une exigence majeure dans les pays à forte endémicité comme la Côte d'Ivoire.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Hépatites virales et grossesse – Conclusion\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"Lors du bilan prénatal, les résultats des marqueurs du virus de l'hépatite B sont les suivants : AgHBs négatif, Ac anti-HBs positif, Ac anti-HBc négatif. Cette situation correspond à : (choisir la bonne affirmation)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Femme non vaccinée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Femme vaccinée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Femme avec hépatite chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Femme avec hépatite B guérie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Femme vaccinée\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"AgHBs négatif + Ac anti-HBc négatif = pas de contact avec le virus. L'Ac anti-HBs positif isolé témoigne donc d'une immunité par vaccination. Une hépatite guérie aurait des anti-HBc positifs.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Prévention de l'HVB (1er et 2e cas, contrôle des anti-HBs après vaccination)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"La vaccination de la gestante est-elle nécessaire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Non\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La femme est déjà protégée (anti-HBs positif) : la vaccination n'est plus indiquée. Le cours propose la vaccination seulement quand AgHBs et anti-HBc sont négatifs sans anticorps protecteurs.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Prévention de l'HVB – CAT au cours de la grossesse\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique 1 — Mme Ko Y., 18 ans, G2P1, groupe A négatif, porteuse d'une grossesse de 27 semaines, est admise aux urgences gynécologiques pour altération de l'état général avec fièvre depuis deux jours. L'examen à l'admission par la sage-femme conclut à un tableau de mort fœtale avec chorioamniotite sévère, suite à une RPM depuis une semaine. Une antibiothérapie est immédiatement entreprise avec un bilan infectieux.\",\n       \"text\": \"À l'accouchement de cette patiente, les actions suivantes sont-elles nécessaires chez le nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Immunoprophylaxie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sérovaccination\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Arrêt allaitement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Continuer allaitement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Sérovaccination ; D. Continuer allaitement\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Pour un nouveau-né de mère porteuse de l'AgHBs, le cours prévoit dès la naissance une dose de sérum anti-hépatite B et une dose de vaccin en IM sur deux sites différents (sérovaccination). L'allaitement n'est pas contre-indiqué.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Prévention de l'HVB – 3e cas : après l'accouchement\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'écosystème vaginal normal est composé des micro-organismes suivants : Lesquelles.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Lactobacilles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Staphylocoques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Chlamydiae trachomatis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Candida albicans\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Gardnerella vaginalis\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Trichomonas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Lactobacilles ; B. Staphylocoques ; D. Candida albicans ; E. Gardnerella vaginalis\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La flore vaginale normale est dominée par les lactobacilles (bacilles de Döderlein), avec des germes d'origine cutanée et digestive en faible proportion. Staphylocoques, Candida et Gardnerella peuvent y vivre sans maladie (commensaux). Chlamydia et Trichomonas sont toujours pathogènes (IST).\\n\\nSource : Gynéco L2 IDE version 2025, Leucorrhées – Microbiologie : flore vaginale (p. 133)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une vulvo-vaginite présentant les caractères suivants : leucorrhées blanchâtres, abondantes, grumeleuses, inodores, adhérentes à la paroi vaginale et associées à des prurits intenses est en faveur : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vaginose\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Chlamydiose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mycose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Infection à Trichomonas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Mycose\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Leucorrhées blanches, épaisses, grumeleuses (lait caillé), inodores, adhérentes à la muqueuse avec prurit vulvo-vaginal très intense : c'est la mycose (Candida albicans dans 85 % des cas). La vaginose donne des pertes grises malodorantes, la trichomonase des pertes verdâtres mousseuses.\\n\\nSource : Gynéco L2 IDE version 2025, Leucorrhées – Mycoses vaginales (p. 138-139)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La réanimation du nouveau-né en salle d'accouchement (Maternité) fait appel le plus souvent à 4 techniques, laquelle est la première à mettre en place ? (Cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Injection de solutés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ventilation manuelle au ballon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Désobstruction des voies aériennes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Massage cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Désobstruction des voies aériennes\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La première étape de la réanimation du nouveau-né est la désobstruction des voies aériennes (avec la stimulation). Si le bébé ne respire toujours pas bien, on passe à la ventilation au ballon et au masque, puis on évalue le rythme cardiaque.\\n\\nSource : SONU – PNSME, Réanimation du nouveau-né (p. 71)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les germes suivants, lequel est le plus fréquemment responsable d'une infection urinaire au cours de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Serratia enterobacter\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Proteus mirabilis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Escherichia coli\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Klebsiella pneumoniae\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Escherichia coli\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au cours des infections urinaires, le germe le plus souvent isolé est Escherichia coli (90 %).\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Infections urinaires et grossesse – Germes en cause\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les infections urinaires suivantes, pouvant survenir au cours de la grossesse, laquelle est la plus fréquente :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cystite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bactériurie asymptomatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pyélonéphrite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Bactériurie asymptomatique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours distingue 3 formes : pyélonéphrite (fébrile), cystite (sans fièvre) et bactériurie asymptomatique (découverte par l'ECBU seul). La bactériurie asymptomatique est la plus fréquente, d'où l'intérêt du dépistage systématique (nitrites, ECBU).\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Infections urinaires et grossesse – Généralités (fréquence : hors cours)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les affirmations suivantes concernant le diabète gestationnel : Laquelle est exacte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Est préexistant à la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Persiste toujours après l'accouchement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Apparaît le plus souvent à 15 semaines\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Apparaît le plus souvent à partir de 24 S\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Est dépisté par la glycémie à jeun au 1er trimestre de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Apparaît le plus souvent à partir de 24 S\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le diabète gestationnel est découvert pour la première fois pendant la grossesse (il n'est pas préexistant). Il apparaît surtout au 2e-3e trimestre, quand l'insulinorésistance augmente, d'où un dépistage après 24 SA. Il régresse le plus souvent après l'accouchement, et la glycosurie est un mauvais test de dépistage.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Diabète et grossesse – Diabète gestationnel\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ménopause précoce est celle survenant avant : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"40 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"45 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"50 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"55 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 40 ans\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La ménopause précoce (insuffisance ovarienne prématurée) est celle qui survient avant 40 ans. L'âge habituel se situe entre 45 et 55 ans.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La phase de préménopause est dominée par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Absence de sécrétion d'œstrogènes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hyperœstrogénie relative\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Augmentation de la progestérone\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Chute de la progestérone\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Hyperœstrogénie relative ; D. Chute de la progestérone\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"En préménopause, les cycles deviennent anovulatoires : le corps jaune ne se forme plus, d'où une chute de la progestérone (insuffisance lutéale). Les œstrogènes persistent sans opposition progestative : c'est l'hyperœstrogénie relative.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Ménopause – Physiopathologie (« insuffisance lutéale… avec une hyperœstrogénie relative »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les bouffées de chaleur de la ménopause présentent les caractères suivants : Lesquels (une réponse fausse annule une réponse vraie)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sensation de chaleur débute au thorax\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sensation de chaleur débute au visage\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Souvent diurne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Souvent nocturne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Associées à des troubles de l'humeur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Sensation de chaleur débute au visage ; D. Souvent nocturne ; E. Associées à des troubles de l'humeur\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La bouffée de chaleur typique débute au visage et au cou, survient surtout la nuit (sueurs nocturnes) et s'accompagne volontiers de troubles de l'humeur (irritabilité, anxiété). Le cours précise qu'elle n'existe que chez certaines femmes.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Ménopause confirmée (bouffées chez certaines femmes) ; caractères : hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les germes suivants, lequel est le plus souvent responsable d'infection génitale haute :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Escherichia coli\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Staphylocoque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Chlamydiae trachomatis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Gonocoque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Chlamydiae trachomatis\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Chlamydia trachomatis est cité en premier parmi les principaux germes des infections génitales hautes (salpingites), devant les entérobactéries, les streptocoques, les staphylocoques et le gonocoque.\\n\\nSource : Gynéco L2 IDE version 2025, Salpingites aiguës – Principaux germes en cause\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La détermination génétique commence à : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"à la fécondation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"à la période embryonnaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"la période fœtale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. à la fécondation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le sexe génétique (XX ou XY) est déterminé dès la fécondation, selon le chromosome X ou Y du spermatozoïde qui pénètre l'ovocyte II.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Fécondation – Déterminisme du sexe génétique (p. 40)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les malformations utéro-génitales suivantes, la ou lesquelles sont compatibles avec la survenue d'une grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Agénésie complète bilatérale de l'utérus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Agénésie bilatérale partielle de l'utérus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Diaphragme vaginal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Diaphragme vaginal\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'agénésie complète bilatérale correspond à l'absence totale d'utérus, et l'agénésie bilatérale partielle (syndrome de Rokitansky) laisse des cornes rudimentaires sans cavité : la grossesse est impossible dans les deux cas. Le diaphragme (cloison) vaginal n'empêche pas la grossesse.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Malformations génitales – Aplasies utérines\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les situations suivantes au cours de la gravido-puerpéralité, la ou lesquelles correspond ou correspondent à la mort fœtale in utero :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mort fœtale à 36 semaines de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mort fœtale lors de l'expulsion fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mort fœtale à 7 cm du travail d'accouchement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mort fœtale à 22 S de grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Mort fœtale à 36 semaines de grossesse ; D. Mort fœtale à 22 S de grossesse\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"La mort fœtale in utero est le décès du fœtus pendant la grossesse, avant l'entrée en travail (22 SA et 36 SA conviennent). Un décès pendant le travail ou l'expulsion est une mort per-partum (intra-partum).\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Mort in utero – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les situations suivantes, laquelle est la plus responsable de mort fœtale in utero :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hépatite virale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Paludisme et grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toxoplasmose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prééclampsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Prééclampsie\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La pré-éclampsie (insuffisance placentaire, HRP) est la cause la plus responsable parmi les propositions : elle entraîne souffrance fœtale, RCIU et mort in utero.\\n\\nSource : SONU L2 SFM 2026 – HTA / pré-éclampsie, Complications fœtales ; Gynécologie-Obstétrique L3 (Pr Djanhan), Causes de la mort in utero\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les situations suivantes peuvent être à l'origine d'une mort fœtale in utero : Lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Grossesse prolongée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dépassement de terme\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accouchement à terme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Accouchement prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Grossesse prolongée ; B. Dépassement de terme\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La grossesse prolongée et le dépassement de terme exposent à une souffrance fœtale chronique puis aiguë, pouvant aller jusqu'à la mort du fœtus (vieillissement placentaire). L'accouchement à terme ou prématuré n'est pas une cause de MFIU.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Grossesse prolongée (complications) et Mort in utero (« grossesse dépassée »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lequel des éléments ci-dessous permettent de confirmer le diagnostic de mort fœtale in utero :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Disparition des mouvements fœtaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Absence de bruit du cœur fœtal à l'auscultation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Montée laiteuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Échographie obstétricale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Diminution du volume utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Échographie obstétricale\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La disparition des mouvements actifs, l'absence de BDC, la montée laiteuse et la diminution du volume utérin orientent le diagnostic. Seule l'échographie obstétricale le confirme (absence d'activité cardiaque).\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Mort in utero – Examens complémentaires : « l'échographie confirme la mort fœtale »\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les complications suivantes, laquelle est liée au maintien de la mort fœtale in utéro pendant plus de deux semaines (rétention d'œuf mort):\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infection amniotique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Coagulopathie (trouble hémostase)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trouble psychologique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Coagulopathie (trouble hémostase)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La rétention prolongée du fœtus mort expose surtout aux troubles de la coagulation (afibrinogénémie, fibrinogène < 1,5 g/l), au-delà de quelques semaines selon Merger. L'infection survient surtout si les membranes sont rompues.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Mort in utero – Complications\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon l'EDS (Enquête Démographique de Santé) de 2021 en Côte d'Ivoire, le taux de décès maternel pour 100 000 naissances vivantes est de : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"385\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"614\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"215\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"512\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 385\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"D'après l'EDS 2021, le ratio de mortalité maternelle en Côte d'Ivoire est de 385 décès pour 100 000 naissances vivantes. Le chiffre de 614 correspond à l'EDS 2012, celui cité dans les cours.\\n\\nSource : (explication hors cours du projet — les cours citent 614 / EDS 2012 : SONU – PNSME)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le décès maternel est tout décès d'une femme survenu au cours de la grossesse ou dans un délai de : ……… jours après sa terminaison, mais ni accidentelle, ni fortuite. (Cocher la bonne réponse).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"62 j\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"32 j\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"52 j\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"42 j\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 42 j\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le décès maternel est tout décès survenu pendant la grossesse ou dans les 42 jours suivant sa terminaison, pour une cause liée à la grossesse ou aggravée par elle, mais ni accidentelle ni fortuite.\\n\\nSource : SONU – PNSME, Définition de la mortalité maternelle ; Document SSR L2 SF 2021\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mortalité maternelle est un indicateur : Cocher les bonnes réponses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"de l'état de santé de la population\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"du taux d'alphabétisation des femmes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"de la qualité des soins obstétricaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"du niveau de développement économique du pays\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"de l'âge moyen de survie de la population\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. de l'état de santé de la population ; C. de la qualité des soins obstétricaux ; D. du niveau de développement économique du pays\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La mortalité maternelle reflète l'état de santé de la population, la qualité des soins obstétricaux (accès aux SONU, personnel qualifié) et le niveau de développement économique du pays.\\n\\nSource : (explication hors cours du projet ; Document SSR L2 SF 2021 : indicateur sanitaire)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les causes des décès maternels suivantes sont des causes directes : Lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémoglobinopathie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Perforation utérine suite à un avortement provoqué\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hématomes péri génitaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Neuropaludisme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Placenta prævia hémorragique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Perforation utérine suite à un avortement provoqué ; C. Hématomes péri génitaux ; E. Placenta prævia hémorragique\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Les causes obstétricales directes résultent des complications de la grossesse, du travail ou des suites de couches : hémorragies (placenta prævia, hématomes péri-génitaux) et avortements à risque (perforation utérine). L'hémoglobinopathie et le neuropaludisme sont des causes indirectes.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Principales causes de décès maternels – causes directes / indirectes (p. 75)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions ci-dessous, lesquelles font partie des stratégies nationales de lutte contre les décès maternels :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Audit et revue des décès maternels\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bonne application des SONU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La CPN de qualité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La planification familiale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Accouchements non assistés par un personnel qualifié\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Audit et revue des décès maternels ; B. Bonne application des SONU ; C. La CPN de qualité ; D. La planification familiale\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les stratégies nationales contre la mortalité maternelle comprennent l'audit et la revue des décès, les SONU, la CPN de qualité et la planification familiale. Les accouchements non assistés sont au contraire un facteur de mortalité.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS) (facteurs de mortalité) ; SONU – PNSME (stratégie partielle, hors cours)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'audit des décès maternels permet de : Cocher les bonnes réponses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire des recommandations\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sanctionner les auteurs des dysfonctionnements\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Identifier les dysfonctionnements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Améliorer la qualité des soins\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Faire des recommandations ; C. Identifier les dysfonctionnements ; D. Améliorer la qualité des soins\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"L'audit des décès maternels sert à identifier les dysfonctionnements, faire des recommandations et améliorer la qualité des soins. Il est anonyme et non punitif : il ne vise pas à sanctionner.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs suivants de décès maternels, lesquels font partie du deuxième retard :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Coût du transport\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mauvais état des routes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Croyances socioculturelles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Manque de médicaments\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Sous-estimation des symptômes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Absence de personnel qualifié\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Coût du transport ; B. Mauvais état des routes\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le 2e retard (retard dans l'accès / la référence) est lié à la longue distance, au mauvais état des routes, à l'insuffisance des moyens de référence et au faible revenu des ménages (coût du transport). Les croyances relèvent du 1er retard, le manque de médicaments ou de personnel du 3e.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Les trois retards (p. 76) ; SONU L1 2021\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les ébauches de l'appareil génital ne sont pas identiques chez l'embryon féminin et masculin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Au début du développement, les ébauches génitales sont identiques chez l'embryon féminin et masculin (stade indifférencié). Elles se différencient ensuite selon le sexe génétique. L'affirmation est donc fausse.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'agénésie complète bilatérale est souvent associée à une agénésie rénale bilatérale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'agénésie complète bilatérale (absence totale d'utérus) est une malformation rare, souvent associée à d'autres malformations comme l'agénésie rénale bilatérale.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Malformations génitales – Aplasie utérine\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ménopause peut être muette (aucun signe).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Seule l'aménorrhée secondaire est constante. Les bouffées de chaleur et les autres signes n'existent que chez certaines femmes : la ménopause peut donc être muette.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Ménopause – Examen clinique\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement antiviral chez une gestante porteuse du virus de l'hépatite B est toujours obligatoire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le traitement antiviral n'est pas systématique pour toute porteuse de l'AgHBs : il dépend de la réplication virale, et la prévention repose aussi sur la sérovaccination du nouveau-né.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hydramnios est un facteur de risque de procidence du cordon.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hydramnios (excès de liquide amniotique) favorise la procidence du cordon, surtout lors de la rupture des membranes, car la présentation reste haute et mal appliquée.\\n\\nSource : Gynéco L2 IDE version 2025, Rupture artificielle des membranes (risque de procidence) ; facteurs : hors cours\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'accouchement de siège, en cas de rétention des épaules, l'attitude de Lovset est préconisée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En cas de rétention de la tête dernière, on utilise la manœuvre de Mauriceau (ou Bracht si la tête est bien fléchie).\\n\\nSource : SONU L3, Accouchement du siège (p. 72-78)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infertilité se définit comme l'absence de survenue d'une grossesse après 1 an de rapports sexuels réguliers sous contraception.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'infertilité est l'absence de grossesse après plus de 12 mois de rapports sexuels réguliers sans contraception. L'affirmation dit « sous contraception » : elle est fausse.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Infertilité – Définition OMS\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'avortement spontané est le plus souvent hémorragique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'avortement spontané associe douleurs et métrorragies plus ou moins abondantes, mais l'hémorragie grave y est rare. C'est l'avortement provoqué (clandestin) qui est le plus souvent hémorragique.\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Avortement (CAT : « infection et hémorragie sont rares en cas d'avortement spontané » ; avortement provoqué « le plus souvent hémorragique »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ménarche précoce est un facteur de risque de cancer du sein.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une longue durée d'activité ovarienne (puberté précoce avant 13 ans, ménopause tardive après 55 ans) est un facteur de risque hormonal du cancer du sein.\\n\\nSource : Gynéco L2 IDE version 2025, Cancer du sein – Facteurs de risque (p. 120-121)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les gamètes femelles sont appelés les ovocytes II\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le gamète femelle libéré à l'ovulation et fécondé par le spermatozoïde est l'ovocyte II (ovocyte de 2e ordre).\\n\\nSource : Cours Gynéco-Obstétrique (1re année commune INFAS), Fécondation – Déterminisme du sexe (« pénètre dans l'ovocyte II »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La maturation pulmonaire fœtale se fait avec des corticoïdes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La corticothérapie anténatale (bétaméthasone – Célestène® 12 mg IM, répétée 24 h plus tard) réduit le risque de détresse respiratoire du prématuré.\\n\\nSource : MAP – Menace d'accouchement prématuré (PDF), Traitement – Corticothérapie anténatale\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la rupture utérine, le toucher vaginal doit être réalisé avec prudence pour ne pas déclencher une hémorragie cataclysmique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le TV prudent pour éviter une hémorragie cataclysmique concerne le placenta prævia (TV intracervical interdit). Dans la rupture utérine, la présentation n'est plus perçue au TV et le diagnostic repose sur la clinique et la révision utérine.\\n\\nSource : Gynéco L2 IDE version 2025, Placenta prævia (TV) et Rupture utérine (signes physiques)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant né de mère infectée par le VIH doit bénéficier de tous les vaccins du programme élargi de vaccination.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'enfant né de mère VIH+ suit le calendrier du PEV comme les autres enfants (BCG + VPO0 à la naissance, puis PEV à partir de 6 semaines), sauf contre-indication liée à une infection symptomatique.\\n\\nSource : SONU – PNSME, Soins du nouveau-né (vaccination) ; VIH : hors cours\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les fibromes sous séreux sont le plus souvent responsables de ménorragies.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les ménorragies sont surtout dues aux fibromes sous-muqueux (et interstitiels), qui déforment la cavité utérine. Les fibromes sous-séreux donnent plutôt des signes de compression ou une torsion s'ils sont pédiculés.\\n\\nSource : Gynéco L2 IDE version 2025, Fibrome utérin – Complications (sous-séreux pédiculé : torsion)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la cystite isolée l'infection est localisée au niveau du bas appareil urinaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La cystite est l'infection urinaire basse (vessie), sans fièvre. La pyélonéphrite est l'infection haute.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Infections urinaires et grossesse – Généralités\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les grossesses gémellaires bizygotes ; plus la division de l'œuf est tardive, plus elle pourra aboutir à des siamois.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ce phénomène concerne exclusivement les grossesses gémellaires monozygotes (univitellines, issues de la division d'un seul œuf fécondé) : lorsque cette division survient très tardivement (après le 13e jour post-fécondation), elle est incomplète et donne naissance à des jumeaux conjoints (siamois). Les grossesses dizygotes proviennent de deux œufs distincts sans division.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Embryologie des grossesses gémellaires monozygotes.\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La révision utérine ne peut pas être réalisée après une césarienne par risque de couper les fils de hystérorraphie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La révision utérine est même indiquée après un accouchement par voie basse sur utérus cicatriciel, pour rechercher une rupture. Lors d'une césarienne, l'utérus est exploré directement à ciel ouvert : il n'y a pas de « fils à couper ».\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Révision utérine – Indications\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rupture utérine est la principale cause des métrorragies du 3è trimestre de grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les principales causes de métrorragies du 3e trimestre sont le placenta prævia et l'HRP. La rupture utérine survient surtout pendant le travail et ne donne qu'une petite quantité de sang.\\n\\nSource : Gynéco L2 IDE version 2025, Placenta prævia ; Rupture utérine (« métrorragies : petite quantité de sang »)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un couple de groupe sanguin 0 ne peut donner naissance qu'à des enfants de groupe O.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Des parents de groupe O ont tous deux le génotype OO (gène récessif) : ils ne peuvent transmettre que l'allèle O, et leurs enfants sont tous de groupe O.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j2-sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le port du préservatif est un moyen de prévention de la rubéole au cours de la grossesse.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La rubéole se prévient par la vaccination avant la grossesse et l'éviction des contacts avec les malades.\\n\\nSource : Gynécologie-Obstétrique L3 (Pr Djanhan), Rubéole et grossesse\",\n       \"sourceDoc\": \"Prépa D.E — J2 Gynéco-obstétrique SF3 (corrigé expliqué)\",\n       \"sourceFile\": \"J2_GYNECO_SF3_J2_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
